mapper.select:
SELECT COUNT(1)
FROM MCP_REQUEST_OSST@DL_MCP T1
WHERE 1 = 1
  AND T1.MVNO_ORD_NO = LPAD(#{mvnoOrdNo}, 14, '0')
  AND T1.PRGR_STAT_CD = #{prgrStatCd}

    AND T1.RSLT_CD = #{rsltCd}

mapper.insert:
INSERT INTO MCP_REQUEST_OSST@DL_MCP (
    MVNO_ORD_NO
  , SEQ
  , OSST_ORD_NO
  , PRGR_STAT_CD
  , RSLT_CD
  , TLPH_NO_STAT_CD
  , ASGN_AGNC_ID
  , TLPH_NO_OWN_CMPN_CD
  , OPEN_SVC_IND_CD
  , ENCD_TLPH_NO
  , TLPH_NO
  , IF_TYPE
  , NSTEP_GLOBAL_ID
  , REGST_DTTM
  , RSLT_DT
) VALUES (
    LPAD(#{mvnoOrdNo}, 14, '0')
  , NVL((SELECT MAX(SEQ + 1) FROM MCP_REQUEST_OSST@DL_MCP WHERE MVNO_ORD_NO = LPAD(#{mvnoOrdNo}, 14, '0')), 1)
  , #{osstOrdNo}
  , #{prgrStatCd}
  , #{rsltCd}
  , #{tlphNoStatCd}
  , #{asgnAgncId}
  , #{tlphNoOwnCmpnCd}
  , #{openSvcIndCd}
  , #{encdTlphNo}
  , #{tlphNo}
  , NVL(#{ifType, jdbcType=VARCHAR}, 'WEB')
  , #{nstepGlobalId}
  , SYSDATE
  , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
)

mapper.select:
SELECT ETC1
FROM CMN_GRP_CD_MST
WHERE GRP_ID = #{grpId}
  AND CD_VAL = #{cdVal}
  AND ROWNUM = 1
